content.text:
Perfecto, ya tengo toda la información. Aquí va el código y las indicaciones:

---

## 1. Función `crearTooltipPersonalizado` — agregar en [tooltips.js](public/componentes/componentes/tooltips.js)

Agregar esta función al final del archivo, antes de la línea del `DOMContentLoaded` (antes de la línea 86):

```javascript
/**
 * Crear un tooltip personalizado con clase custom para contenido tabular
 * 
 * @param {object} componente Datos del componente.
 * @returns {string} Información del tooltip.
 * @author Esperanza Olivo
 */
function crearTooltipPersonalizado(componente) {
    return `
        data-bs-toggle="tooltip"
        data-bs-placement="${componente.placement ? componente.placement : 'top'}"
        data-bs-container="${componente.container ? componente.container : 'body'}"
        data-bs-trigger="${componente.trigger ? componente.trigger : 'hover'}"
        data-bs-html="true"
        data-bs-custom-class="tooltip-personalizado"
        data-bs-title="${componente.content}"
    `;
}
```

---

## 2. CSS — agregar en [planes.css](public/css/empresa/planes.css)

Agregar al final del archivo:

```css
.tooltip-personalizado .tooltip-inner {
    max-width: 350px;
    text-align: left;
    padding: 10px 14px;
}

.tooltip-personalizado .tooltip-inner table {
    width: 100%;
    border-collapse: collapse;
}

.tooltip-personalizado .tooltip-inner table td {
    padding: 3px 0;
    vertical-align: middle;
}

.tooltip-personalizado .tooltip-inner table td.td-icono {
    width: 22px;
    padding-right: 8px;
}

.tooltip-personalizado .tooltip-inner table td.td-nombre {
    text-align: left;
    white-space: nowrap;
}

.tooltip-personalizado .tooltip-inner table td.td-valor {
    text-align: right;
    padding-left: 16px;
    white-space: nowrap;
}

.tooltip-personalizado .tooltip-inner table tr.fila-encabezado td {
    font-weight: bold;
    padding-bottom: 6px;
}
```

---

## 3. Función `generarTooltipConsumosPruebas` actualizada — reemplazar en [planes.js:591-621](public/js/empresa/planes/planes.js#L591-L621)

Reemplazar la función existente por:

```javascript
function generarTooltipConsumosPruebas(consumos, total_unidades, pruebas) {
    if (!pruebas || pruebas.length === 0) {
        return 'Sin datos de consumo';
    }
    let consumos_por_prueba = [];

    pruebas.forEach(prueba => {
        consumos_por_prueba.push({ nombre: prueba.nombre, cantidad: 0 });
    });

    if (consumos && consumos.length > 0) {
        consumos.forEach(consumo => {
            if (consumo.agenda?.prueba?.nombre) {
                let nombre = consumo.agenda.prueba.nombre;
                let prueba = consumos_por_prueba.find(p => p.nombre === nombre);
                if (prueba) {
                    prueba.cantidad++;
                }
            }
        });
    }

    let filas = consumos_por_prueba.map(prueba => {
        let nombre = prueba.nombre.replace(/&/g, '&amp;');
        let ruta = slugify(prueba.nombre);
        return `<tr>
            <td class='td-icono'><img src='/imagenes/logos/pruebas/${ruta}.png' width='14' height='14'></td>
            <td class='td-nombre'>${nombre}</td>
            <td class='td-valor'>${prueba.cantidad}</td>
        </tr>`;
    }).join('');

    return `<table>
        <tr class='fila-encabezado'>
            <td colspan='2' class='td-nombre'>Unidades consumidas</td>
            <td class='td-valor'>${total_unidades ?? 0}</td>
        </tr>
        ${filas}
    </table>`;
}
```

---

## 4. Función `generarTooltipPruebasPlan` actualizada — reemplazar en [planes.js:562-580](public/js/empresa/planes/planes.js#L562-L580)

Reemplazar la función existente por:

```javascript
function generarTooltipPruebasPlan(pruebas, plan_nombre = '') {
    if (!pruebas || pruebas.length === 0) return 'Sin pruebas asignadas';

    let encabezado = '';
    if (plan_nombre) {
        encabezado = `<tr class='fila-encabezado'>
            <td colspan='2' class='td-nombre'>${plan_nombre.replace(/&/g, '&amp;')}</td>
        </tr>`;
    }

    let filas = pruebas.map(prueba => {
        let nombre = prueba.nombre?.replace(/&/g, '&amp;') ?? 'Prueba';
        let ruta = slugify(prueba.nombre ?? '');
        return `<tr>
            <td class='td-icono'><img src='/imagenes/logos/pruebas/${ruta}.png' width='14' height='14'></td>
            <td class='td-nombre'>${nombre}</td>
        </tr>`;
    }).join('');

    return `<table>${encabezado}${filas}</table>`;
}
```

---

## 5. Dónde cambiar `crearTooltip` por `crearTooltipPersonalizado` en [planes.js](public/js/empresa/planes/planes.js)

Hay **2 lugares** donde se usan estas funciones de tooltip con contenido de pruebas/consumos:

**Lugar 1 — Línea 110** (tooltip del icono de tipo de prueba):
```javascript
// Cambiar crearTooltip por crearTooltipPersonalizado
${crearTooltipPersonalizado({
    placement: 'top',
    content: generarTooltipPruebasPlan(
        empresa_plan.pruebas,
        plan.nombre
    )
})}
```

**Lugar 2 — Línea 159** (tooltip de consumos de unidades):
```javascript
// Cambiar crearTooltip por crearTooltipPersonalizado
<div class="col-4 pe-8" ${crearTooltipPersonalizado({
    placement: 'top',
    content: generarTooltipConsumosPruebas(empresa_plan?.consumos ?? [], unidades_consumidas ?? 0, empresa_plan.pruebas ?? [])
})}>
```

---

## Resumen de cambios

| Archivo | Acción |
|---|---|
| [tooltips.js](public/componentes/componentes/tooltips.js) | Agregar `crearTooltipPersonalizado` antes de línea 86 |
| [planes.css](public/css/empresa/planes.css) | Agregar estilos `.tooltip-personalizado` al final |
| [planes.js:562-580](public/js/empresa/planes/planes.js#L562-L580) | Reemplazar `generarTooltipPruebasPlan` |
| [planes.js:591-621](public/js/empresa/planes/planes.js#L591-L621) | Reemplazar `generarTooltipConsumosPruebas` |
| [planes.js:110](public/js/empresa/planes/planes.js#L110) | Cambiar `crearTooltip` → `crearTooltipPersonalizado` |
| [planes.js:159](public/js/empresa/planes/planes.js#L159) | Cambiar `crearTooltip` → `crearTooltipPersonalizado` |

La clave del cambio es que el contenido ahora usa `<table>` con clases CSS (`td-icono`, `td-nombre`, `td-valor`) en lugar de texto separado por `<br>`, lo que permite la alineación en columnas que se ve en la primera imagen. La clase `tooltip-personalizado` amplía el `max-width` del tooltip para que la tabla tenga espacio suficiente.

