                let prueba = consumos_por_prueba.find(p => p.nombre === nombre);
                if (prueba) {
                    prueba.cantidad++;
                }
            }
        });
    }

    let filas = consumos_por_prueba.map(prueba => {
        let nombre = prueba.nombre.replace(/&/g, '&amp;');
        let ruta = slugify(prueba.nombre);
        return `<tr>
            <td class='td-icono'><img src='/imagenes/logos/pruebas/${ruta}.png' width='14' height='14'></td>
            <td class='td-nombre'>${nombre}</td>
            <td class='td-valor'>${prueba.cantidad}</td>
        </tr>`;
    }).join('');

    return `<table>
