            <td colspan='2' class='td-nombre'>Unidades consumidas</td>
            <td class='td-valor'>${total_unidades ?? 0}</td>
        </tr>
        ${filas}
    </table>`;
}

content.text:
Encontré el problema. Los template literals de las funciones `generarTooltipConsumosPruebas` y `generarTooltipPruebasPlan` generan HTML con **saltos de línea**, y eso rompe el atributo `data-bs-title="..."` porque el navegador interpreta los saltos como fin del atributo y el HTML de la tabla se renderiza directamente en la página.

La solución es que todo el HTML retornado sea en **una sola línea**. Aquí van las correcciones:

---

**`generarTooltipPruebasPlan`** — reemplazar en [planes.js:562-582](public/js/empresa/planes/planes.js#L562-L582):

```javascript
function generarTooltipPruebasPlan(pruebas, plan_nombre = '') {
    if (!pruebas || pruebas.length === 0) return 'Sin pruebas asignadas';

    let encabezado = '';
    if (plan_nombre) {
        encabezado = `<tr class='fila-encabezado'><td colspan='2' class='td-nombre'>${plan_nombre.replace(/&/g, '&amp;')}</td></tr>`;
    }

    let filas = pruebas.map(prueba => {
        let nombre = prueba.nombre?.replace(/&/g, '&amp;') ?? 'Prueba';
        let ruta = slugify(prueba.nombre ?? '');
        return `<tr><td class='td-icono'><img src='/imagenes/logos/pruebas/${ruta}.png' width='14' height='14'></td><td class='td-nombre'>${nombre}</td></tr>`;
    }).join('');

    return `<table>${encabezado}${filas}</table>`;
}
```

---

**`generarTooltipConsumosPruebas`** — reemplazar en [planes.js:593-632](public/js/empresa/planes/planes.js#L593-L632):

```javascript
function generarTooltipConsumosPruebas(consumos, total_unidades, pruebas) {
    if (!pruebas || pruebas.length === 0) {
        return 'Sin datos de consumo';
    }
    let consumos_por_prueba = [];

    pruebas.forEach(prueba => {
        consumos_por_prueba.push({ nombre: prueba.nombre, cantidad: 0 });
    });

    if (consumos && consumos.length > 0) {
        consumos.forEach(consumo => {
            if (consumo.agenda?.prueba?.nombre) {
                let nombre = consumo.agenda.prueba.nombre;
                let prueba = consumos_por_prueba.find(p => p.nombre === nombre);
                if (prueba) {
                    prueba.cantidad++;
                }
            }
        });
    }

    let filas = consumos_por_prueba.map(prueba => {
        let nombre = prueba.nombre.replace(/&/g, '&amp;');
        let ruta = slugify(prueba.nombre);
        return `<tr><td class='td-icono'><img src='/imagenes/logos/pruebas/${ruta}.png' width='14' height='14'></td><td class='td-nombre'>${nombre}</td><td class='td-valor'>${prueba.cantidad}</td></tr>`;
    }).join('');

    return `<table><tr class='fila-encabezado'><td colspan='2' class='td-nombre'>Unidades consumidas</td><td class='td-valor'>${total_unidades ?? 0}</td></tr>${filas}</table>`;
}
```

---

La diferencia clave: todo el HTML de `<table>`, `<tr>`, `<td>` ahora está **en una sola línea** sin saltos ni indentación. Las líneas de los `return` de las `<tr>` dentro del `.map()` también son de una sola línea.

Ya veo el problema. El HTML del `data-bs-title` está correcto, pero **Bootstrap sanitiza el contenido del tooltip** y su lista de elementos permitidos **NO incluye `<table>`, `<tr>`, `<td>`**. Los elimina silenciosamente al renderizar.

En [tooltips.js:69](public/componentes/componentes/tooltips.js#L69), la segunda inicialización no tiene `sanitize: false`, y sobreescribe la primera.

La solución más segura es **no usar tabla** sino `<div>` y `<span>`, que sí están en la lista permitida de Bootstrap. Aquí va el código corregido:

---

## 1. CSS — reemplazar lo que agregaste en [planes.css](public/css/empresa/planes.css)

Quitar los estilos anteriores de `.tooltip-personalizado` y poner estos:

```css
.tooltip-personalizado .tooltip-inner {
    max-width: 350px;
    text-align: left;
    padding: 10px 14px;
}

.tooltip-personalizado .fila-tooltip {
    display: flex;
    align-items: center;
    padding: 3px 0;
}

.tooltip-personalizado .fila-encabezado-tooltip {
    font-weight: bold;
    padding-bottom: 6px;
}

.tooltip-personalizado .icono-tooltip {
    margin-right: 8px;
    flex-shrink: 0;
}

.tooltip-personalizado .nombre-tooltip {
    flex: 1;
    white-space: nowrap;
}

.tooltip-personalizado .valor-tooltip {
    padding-left: 16px;
    text-align: right;
    white-space: nowrap;
}
```

---

## 2. `generarTooltipConsumosPruebas` — reemplazar en [planes.js:593-632](public/js/empresa/planes/planes.js#L593-L632)

```javascript
function generarTooltipConsumosPruebas(consumos, total_unidades, pruebas) {
    if (!pruebas || pruebas.length === 0) {
        return 'Sin datos de consumo';
    }
    let consumos_por_prueba = [];

    pruebas.forEach(prueba => {
        consumos_por_prueba.push({ nombre: prueba.nombre, cantidad: 0 });
    });

    if (consumos && consumos.length > 0) {
        consumos.forEach(consumo => {
            if (consumo.agenda?.prueba?.nombre) {
                let nombre = consumo.agenda.prueba.nombre;
                let prueba = consumos_por_prueba.find(p => p.nombre === nombre);
                if (prueba) {
                    prueba.cantidad++;
                }
            }
        });
    }

    let filas = consumos_por_prueba.map(prueba => {
        let nombre = prueba.nombre.replace(/&/g, '&amp;');
        let ruta = slugify(prueba.nombre);
        return `<div class='fila-tooltip'><img src='/imagenes/logos/pruebas/${ruta}.png' width='14' height='14' class='icono-tooltip'><span class='nombre-tooltip'>${nombre}</span><span class='valor-tooltip'>${prueba.cantidad}</span></div>`;
    }).join('');

    return `<div><div class='fila-tooltip fila-encabezado-tooltip'><span class='nombre-tooltip'>Unidades consumidas</span><span class='valor-tooltip'>${total_unidades ?? 0}</span></div>${filas}</div>`;
}
```

---

## 3. `generarTooltipPruebasPlan` — reemplazar en [planes.js:562-582](public/js/empresa/planes/planes.js#L562-L582)

```javascript
function generarTooltipPruebasPlan(pruebas, plan_nombre = '') {
    if (!pruebas || pruebas.length === 0) return 'Sin pruebas asignadas';

    let encabezado = '';
    if (plan_nombre) {
        encabezado = `<div class='fila-tooltip fila-encabezado-tooltip'><span class='nombre-tooltip'>${plan_nombre.replace(/&/g, '&amp;')}</span></div>`;
    }

    let filas = pruebas.map(prueba => {
        let nombre = prueba.nombre?.replace(/&/g, '&amp;') ?? 'Prueba';
        let ruta = slugify(prueba.nombre ?? '');
        return `<div class='fila-tooltip'><img src='/imagenes/logos/pruebas/${ruta}.png' width='14' height='14' class='icono-tooltip'><span class='nombre-tooltip'>${nombre}</span></div>`;
    }).join('');

    return `<div>${encabezado}${filas}</div>`;
}
```

---

## Resumen del problema

`inicializarTooltips()` inicializa los tooltips **dos veces**: la primera con `sanitize: false`, la segunda sin ella (línea 69). La segunda sobreescribe la primera, y el sanitizador por defecto de Bootstrap **elimina** `<table>`, `<tr>`, `<td>` porque no están en su lista de elementos permitidos. 

Usando `<div>`, `<span>` e `<img>` (que sí están permitidos) + clases CSS (atributo `class` también permitido), el contenido pasa el sanitizador sin problema. No necesitas cambiar nada en [tooltips.js](public/componentes/componentes/tooltips.js).

