/**
 *  Generar el contenido del tooltip para las pruebas asignadas a un plan.
 *
 * @param {array} pruebas Array de objetos de pruebas asignadas.
 * @returns {string} Contenido HTML del tooltip.
 * @author Esperanza Olivo
 */
function generarTooltipPruebasPlan(pruebas, plan_nombre = '') {
    if (!pruebas || pruebas.length === 0) return 'Sin pruebas asignadas';

    let encabezado = '';
    if (plan_nombre) {
        encabezado = `<div class='fila-tooltip fila-encabezado-tooltip'><span class='nombre-tooltip'>${plan_nombre.replace(/&/g, '&amp;')}</span></div>`;
    }

    let filas = pruebas.map(prueba => {
        let nombre = prueba.nombre?.replace(/&/g, '&amp;') ?? 'Prueba';
        let ruta = slugify(prueba.nombre ?? '');
        return `<div class='fila-tooltip'><img src='/imagenes/logos/pruebas/${ruta}.png' width='14' height='14' class='icono-tooltip'><span class='nombre-tooltip'>${nombre}</span></div>`;
    }).join('');

    return `<div>${encabezado}${filas}</div>`;
}

/**
 *  Generar el contenido del tooltip para los consumos de las pruebas asignadas a un plan, agrupados por prueba.
 *
 * @param {array} consumos Array de objetos de consumos del plan.
 * @param {number} total_unidades Total de unidades consumidas del plan.
 * @param {array} pruebas Array de objetos de pruebas asignadas al plan.
 * @returns {string} Contenido HTML del tooltip.
 * @author Esperanza Olivo
 */
function generarTooltipConsumosPruebas(consumos, total_unidades, pruebas) {
     if (!pruebas || pruebas.length === 0) {
        return 'Sin datos de consumo';
    }
    let consumos_por_prueba = [];

    pruebas.forEach(prueba => {
        consumos_por_prueba.push({ nombre: prueba.nombre, cantidad: 0 });
    });

    if (consumos && consumos.length > 0) {
        consumos.forEach(consumo => {
            if (consumo.agenda?.prueba?.nombre) {
                let nombre = consumo.agenda.prueba.nombre;
                let prueba = consumos_por_prueba.find(p => p.nombre === nombre);
                if (prueba) {
                    prueba.cantidad++;
                }
            }
        });
    }

    let filas = consumos_por_prueba.map(prueba => {
        let nombre = prueba.nombre.replace(/&/g, '&amp;');
        let ruta = slugify(prueba.nombre);
        return `<div class='fila-tooltip'><img src='/imagenes/logos/pruebas/${ruta}.png' width='14' height='14' class='icono-tooltip'><span class='nombre-tooltip'>${nombre}</span><span class='valor-tooltip'>${prueba.cantidad}</span></div>`;
    }).join('');

    return `<div><div class='fila-tooltip fila-encabezado-tooltip'><span class='nombre-tooltip'>Unidades consumidas</span><span class='valor-tooltip'>${total_unidades ?? 0}</span></div>${filas}</div>`;
}

content.text:
Encontré el problema. El CSS **no se agregó** a [planes.css](public/css/empresa/planes.css) — el archivo solo tiene las 10 líneas originales. Sin esos estilos, no hay `display: flex`, no hay ancho adecuado del tooltip, y todo se apila sin alineación.

Necesitas agregar esto al final de [planes.css](public/css/empresa/planes.css):

```css
.tooltip-personalizado {
    --bs-tooltip-max-width: 350px;
}

.tooltip-personalizado .tooltip-inner {
    max-width: 350px;
    text-align: left;
    padding: 10px 14px;
}

.tooltip-personalizado .fila-tooltip {
    display: flex;
    align-items: center;
    padding: 3px 0;
}

.tooltip-personalizado .fila-encabezado-tooltip {
    font-weight: bold;
    padding-bottom: 6px;
}

.tooltip-personalizado .icono-tooltip {
    margin-right: 8px;
    flex-shrink: 0;
}

.tooltip-personalizado .nombre-tooltip {
    flex: 1;
    white-space: nowrap;
}

.tooltip-personalizado .valor-tooltip {
    padding-left: 16px;
    text-align: right;
    white-space: nowrap;
}
```

Adicionalmente, en [tooltips.js:69](public/componentes/componentes/tooltips.js#L69) la segunda inicialización sobreescribe la primera **sin** `sanitize: false`. Cambia esa línea por:

```javascript
$('[data-bs-toggle="tooltip"]').each(function () { new bootstrap.Tooltip(this, { sanitize: false, html: true }); });
```

Esto asegura que todos los tooltips permitan el HTML con `div`/`span` sin que el sanitizador interfiera.

Tienes razón, el problema de fondo es que poner HTML complejo dentro de `data-bs-title` pasa por el sanitizador de Bootstrap y se pierde contenido. El enfoque correcto es **no poner el HTML en el atributo** sino crearlo por JavaScript directamente. Aquí va la solución definitiva:

---

## 1. Reemplazar `crearTooltipPersonalizado` en [tooltips.js](public/componentes/componentes/tooltips.js) (líneas 80-97)

Reemplazar toda la función y agregar la variable y función nueva:

```javascript
let tooltips_personalizados_contenido = {};

/**
 * Crear un tooltip personalizado con contenido complejo HTML
 * 
 * @param {object} componente Datos del componente.
 * @returns {string} Atributos para el elemento.
 * @author Esperanza Olivo
 */
function crearTooltipPersonalizado(componente) {
    let tooltip_id = 'tp_' + Math.random().toString(36).substr(2, 9);
    tooltips_personalizados_contenido[tooltip_id] = componente.content;
    return `data-tooltip-personalizado="${tooltip_id}" data-bs-placement="${componente.placement || 'top'}"`;
}

/**
 * Inicializar los tooltips personalizados vía JS API (sin pasar por data-bs-title)
 * 
 * @returns {void}
 * @author Esperanza Olivo
 */
function inicializarTooltipsPersonalizados() {
    document.querySelectorAll('[data-tooltip-personalizado]').forEach(elemento => {
        let tooltip_id = elemento.getAttribute('data-tooltip-personalizado');
        let contenido = tooltips_personalizados_contenido[tooltip_id];
        if (!contenido) return;
        let instancia = bootstrap.Tooltip.getInstance(elemento);
        if (instancia) instancia.dispose();
        new bootstrap.Tooltip(elemento, {
            html: true,
            sanitize: false,
            placement: elemento.getAttribute('data-bs-placement') || 'top',
            customClass: 'tooltip-personalizado',
            title: contenido,
            container: 'body',
            trigger: 'hover',
        });
    });
}
```

---

## 2. En [planes.js](public/js/empresa/planes/planes.js) línea 295

Después de `inicializarTooltips();` agregar:

```javascript
inicializarTooltipsPersonalizados();
```

Quedaría:
```javascript
$('#listado-planes').html(contenido);
