    if (!pruebas || pruebas.length === 0) return 'Sin pruebas asignadas';

    let encabezado = '';
    if (plan_nombre) {
        encabezado = `<div style="display:flex;align-items:center;font-weight:bold;padding-bottom:6px"><span>${plan_nombre.replace(/&/g, '&amp;')}</span></div>`;
    }

    let filas = pruebas.map(prueba => {
        let nombre = prueba.nombre?.replace(/&/g, '&amp;') ?? 'Prueba';
        let ruta = slugify(prueba.nombre ?? '');
        return `<div style="display:flex;align-items:center;padding:3px 0"><img src='/imagenes/logos/pruebas/${ruta}.png' width='14' height='14' style="margin-right:8px;flex-shrink:0"><span style="flex:1;white-space:nowrap">${nombre}</span></div>`;
    }).join('');

    return `<div>${encabezado}${filas}</div>`;
}
```

